// Normalize Push Hook: loop commits[], extract DEV-NN references
const payload = $json;
const commits = payload.commits || [];
const branch = (payload.ref || '').replace('refs/heads/', '');
const projectId = payload.project_id || (payload.project && payload.project.id);
const items = [];

for (const commit of commits) {
  const msg = commit.message || '';
  const refs = classifyMessage(msg);
  for (const r of refs) {
    // A "close" on a push with no MR context becomes "mention" (In Progress only, not In Review)
    // unless the commit is on the default branch (merged) -> handled by reducer via branch check
    const action = r.action; // close, reopen, mention
    items.push({
      json: {
        issueKey: r.issueKey,
        action: action,
        commitSha: commit.id,
        commitUrl: commit.url || '',
        commitMessage: msg,
        commitTitle: commit.title || msg.split('\n')[0],
        author: (commit.author && commit.author.name) || '',
        branch: branch,
        isDefaultBranch: branch === (payload.project && payload.project.default_branch),
        projectId: projectId,
        source: 'push',
      },
    });
  }
}
return items;

