// Normalize Merge Request Hook
const payload = $json;
const attrs = payload.object_attributes || {};
const action = attrs.action;
const mrIid = attrs.iid;
const mrUrl = attrs.url || '';
const mrTitle = attrs.title || '';
const sourceBranch = attrs.source_branch || '';
const targetBranch = attrs.target_branch || '';
const description = attrs.description || '';
const items = [];

if (action === 'open' || action === 'update') {
  // Parse description for closes + mentions
  const refs = classifyMessage(description);
  for (const r of refs) {
    // close in an open MR -> In Review; mention -> mr-open
    const act = r.action === 'close' ? 'close-in-mr' : 'mr-open';
    items.push({
      json: {
        issueKey: r.issueKey,
        action: act,
        mrIid: mrIid,
        mrUrl: mrUrl,
        mrTitle: mrTitle,
        sourceBranch: sourceBranch,
        targetBranch: targetBranch,
        source: 'mr',
      },
    });
  }
  // Also scan fetched commits if present (passed via $items or $json.commits)
  // The Get MR Commits node output is in $json.commits when wired in
} else if (action === 'merge') {
  // Merged -> Done for closing keywords; mention stays mention
  const refs = classifyMessage(description);
  // also check last_commit
  const lastCommitMsg = (attrs.last_commit && attrs.last_commit.message) || '';
  const lastRefs = classifyMessage(lastCommitMsg);
  const allRefs = refs.concat(lastRefs);
  const seen = new Set();
  for (const r of allRefs) {
    if (seen.has(r.issueKey + r.action)) continue;
    seen.add(r.issueKey + r.action);
    const act = r.action === 'close' ? 'merged' : (r.action === 'reopen' ? 'reopen' : 'mention');
    items.push({
      json: {
        issueKey: r.issueKey,
        action: act,
        mrIid: mrIid,
        mrUrl: mrUrl,
        mrTitle: mrTitle,
        mergeCommitSha: attrs.merge_commit_sha || '',
        source: 'mr',
      },
    });
  }
} else if (action === 'close') {
  // Closed without merge -> guarded downgrade to Todo
  const refs = classifyMessage(description);
  for (const r of refs) {
    items.push({
      json: {
        issueKey: r.issueKey,
        action: 'mr-closed',
        mrIid: mrIid,
        mrUrl: mrUrl,
        mrTitle: mrTitle,
        source: 'mr',
      },
    });
  }
}
return items;

